BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT NOT NULL UNIQUE, password_hash TEXT, display_name TEXT, status TEXT NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE projects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), name TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), project_id UUID REFERENCES projects(id), title TEXT, status TEXT NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), session_id UUID NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('user','keystone')), content TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE assets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_id UUID NOT NULL REFERENCES users(id), project_id UUID REFERENCES projects(id), media_type TEXT NOT NULL, mime_type TEXT NOT NULL, storage_provider TEXT NOT NULL, storage_key TEXT NOT NULL, byte_size BIGINT NOT NULL, status TEXT NOT NULL DEFAULT 'available', metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ, UNIQUE(storage_provider,storage_key));
CREATE TABLE requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), session_id UUID REFERENCES sessions(id), message_id UUID REFERENCES messages(id), request_text TEXT, preferences JSONB NOT NULL DEFAULT '{}'::jsonb, state TEXT NOT NULL DEFAULT 'created', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE TABLE cognitive_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), request_id UUID NOT NULL REFERENCES requests(id), model_id TEXT NOT NULL, provider_id TEXT NOT NULL, prompt_hash TEXT NOT NULL, prompt_version TEXT NOT NULL, proposed_action JSONB NOT NULL, confidence DOUBLE PRECISION, metrics JSONB NOT NULL DEFAULT '{}'::jsonb, started_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE TABLE authority_decisions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), request_id UUID NOT NULL REFERENCES requests(id), cognitive_run_id UUID REFERENCES cognitive_runs(id), decision TEXT NOT NULL CHECK (decision IN ('approve','deny','replan')), capability_id TEXT, provider_id TEXT, sanitized_arguments JSONB NOT NULL DEFAULT '{}'::jsonb, reason_codes JSONB NOT NULL DEFAULT '[]'::jsonb, policy_bundle_version TEXT NOT NULL, capability_registry_version TEXT NOT NULL, harness_bundle_version TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE jobs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), request_id UUID NOT NULL REFERENCES requests(id), authority_decision_id UUID NOT NULL REFERENCES authority_decisions(id), user_id UUID NOT NULL REFERENCES users(id), capability_id TEXT NOT NULL, provider_id TEXT NOT NULL, workflow_id TEXT NOT NULL, workflow_version TEXT NOT NULL, state TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 100, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), error_code TEXT, error_detail JSONB);
CREATE TABLE compiled_prompts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), request_id UUID NOT NULL REFERENCES requests(id), job_id UUID REFERENCES jobs(id), compiler_id TEXT NOT NULL, compiler_version TEXT NOT NULL, capability_id TEXT NOT NULL, provider_id TEXT NOT NULL, positive_prompt TEXT NOT NULL, negative_prompt TEXT, parameters JSONB NOT NULL DEFAULT '{}'::jsonb, provenance JSONB NOT NULL, prompt_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE harness_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), request_id UUID REFERENCES requests(id), job_id UUID REFERENCES jobs(id), harness_id TEXT NOT NULL, harness_version TEXT NOT NULL, phase TEXT NOT NULL, verdict TEXT NOT NULL CHECK (verdict IN ('pass','warn','fail')), score DOUBLE PRECISION, reason_codes JSONB NOT NULL DEFAULT '[]'::jsonb, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor_type TEXT NOT NULL, actor_id TEXT, event_type TEXT NOT NULL, request_id UUID, job_id UUID, data JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
COMMIT;
